/* ===== Layer 4 rev 4 mock-up · Portfolio (six owner-approved tabs), Sites directory, Financials root, pilot request ===== */
const PTABS = [['Overview','portfolio'],['Act first','portfolio/act-first'],['Outcomes by site','portfolio/outcomes-by-site'],['Opportunity','portfolio/opportunity'],['What changed','portfolio/what-changed'],['Scope & coverage','portfolio/scope']];
const ptabs = s => tabRow(PTABS,s.ptab||s.id);
const sec = (title,body,sub='',right='',id='') => `<section class="panel"${id?` id="${id}"`:''}><div class="panel-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${right}</div>${body}</section>`;
const region = (label,html) => `<div class="table-wrap scroll-region" tabindex="0" role="region" aria-label="${escapeHtml(label)}">${html}</div>`;
const siteLink = sk => link(`site/${sk}`,SK[sk].name,'strong');

/* ---------- factor table (outcome → factors → leaves; plan against October at every factor) ---------- */
const BOUND = {off:['Outside its limit','red'],at:['At its limit','amber'],near:['Near its limit','amber'],ok:['Within its limit','green']};
function devText(n){if(n.obs)return '<span class="muted">observed</span>';
 if(n.plan!=null&&n.actual!=null&&typeof n.plan==='number'){const d=r2(n.actual-n.plan);if(Math.abs(d)<0.005)return 'on plan';return (d>0?'+':'−')+fmtU(Math.abs(d),n.unit);}
 if(n.dev!=null)return (n.dev>0?'+':'−')+fmtU(Math.abs(n.dev),n.unit);return '—';}
function factorTable(sk,opts={}){const rows=[];
 walk(tree(sk),(n,d)=>{if(opts.depth!=null&&d>opts.depth)return;
  const lab=`<div class="fac" style="--d:${d}">${d?'<span class="fac-branch" aria-hidden="true">└</span>':''}<div><b>${n.label}</b>${n.residual?' <span class="badge outline">not explained yet</span>':''}<small>${n.how}</small>${n.bound?`<small class="bnd">${badge(...BOUND[n.bound.state])} ${n.bound.text}</small>`:''}</div></div>`;
  const pl=n.plan!=null?fmtU(n.plan,n.unit):'<span class="muted">not declared</span>';
  const ac=n.actual!=null?fig(`node:${sk}:${n.id}`,fmtU(n.actual,n.unit)):'—';
  rows.push(`<tr class="${n.residual?'resid':''} ${d===0?'root':''}"><th scope="row">${lab}</th><td>${n.obs&&n.plan==null?'<span class="muted">—</span>':pl}</td><td>${ac}</td><td>${devText(n)}</td><td>${n.eff!=null&&!n.obs?(n.evd&&n.actual==null?fig(n.evd,usd(n.eff,true)):usd(n.eff,true)):'—'}</td><td>${ec(n.cls)}</td><td>${n.lens?lensTag(n.lens):''}</td><td>${n.dec?link(`decision/${n.dec}`,'Decision →'):''}</td></tr>`);});
 const cost=OPS[SK[sk].op].kind==='cost';
 return region(`Factor structure for ${SK[sk].name}`,`<table class="ftab"><thead><tr><th>Factor and how it composes</th><th>Plan</th><th>October</th><th>Deviation</th><th>Effect on ${cost?'cost (+ lower)':'contribution'}</th><th>Evidence</th><th>Outcome</th><th></th></tr></thead><tbody>${rows.join('')}</tbody></table>`);}

/* ---------- value chain strip (stages with leaks between them) ---------- */
function chainStrip(op,sk){const o=OPS[op];let st;
 if(o.vertical==='mini'){const C=sk?{...siteM(sk).period.actual,plan_billed_kwh:siteM(sk).period.plan.billed_kwh,plan_revenue:siteM(sk).period.plan.revenue}:o.t.portfolio.chain;
  const loss=sk?(C.technical_loss_kwh??C.expected_technical_loss_kwh)+(C.unexplained_kwh||0):C.delivered_kwh-C.metered_kwh,unb=sk?(C.adjustments_kwh+(C.unbilled_mapping_kwh||0)):C.metered_kwh-C.billed_kwh;
  st=[['Usable capacity','Not available yet','needs the energy management export by time window','na'],['leak','idle capacity: not available yet'],['Delivered',num(C.delivered_kwh)+' kWh','Measured'],['leak',`losses ${num(loss)} kWh`],['Metered',num(C.metered_kwh)+' kWh','Measured'],['leak',`adjustments and unmapped meters ${num(unb)} kWh`],
   ['Billed',num(C.billed_kwh)+' kWh',`plan ${num(C.plan_billed_kwh)} · Recorded`],['leak',''],['Revenue',usd(C.revenue),`plan ${usd(C.plan_revenue)} · Recorded`],['leak',`in transit ${usd(C.in_transit)} · outstanding ${usd(C.outstanding)}`],['Cash collected',usd(C.collected),'Recorded']];}
 else if(o.vertical==='cold'){const t=o.t,C=sk?{capacity_crate_days:t.capacity_crate_days_oct,occupied_crate_days:siteM(sk).period.actual.crate_days,plan_crate_days:siteM(sk).period.plan.crate_days,revenue:siteM(sk).period.actual.revenue,plan_revenue:siteM(sk).period.plan.revenue,collected:siteM(sk).period.actual.collected,outstanding:siteM(sk).period.actual.outstanding}:t.portfolio.chain;
  st=[['Capacity',num(C.capacity_crate_days)+' crate-days','Recorded'],['leak',`idle ${num(C.capacity_crate_days-C.occupied_crate_days)} crate-days`],['Occupied',num(C.occupied_crate_days)+' crate-days',`plan ${num(C.plan_crate_days)} · Recorded`],['leak','no unbilled occupancy recorded'],['Chargeable',num(C.revenue/t.prices.storage_usd_per_crate_day)+' crate-days','Calculated from records'],['leak',''],['Revenue',usd(C.revenue),`plan ${usd(C.plan_revenue)} · Recorded`],['leak',`outstanding ${usd(C.outstanding)}`],['Cash collected',usd(C.collected),'Recorded']];}
 else {const C=sk?{delivered_kwh:siteM(sk).period.actual.kwh,departures_required:siteM(sk).period.actual.departures_required,departures_met:siteM(sk).period.actual.departures_met}:o.t.portfolio.chain;const dl=sk==='ruiru'?['3,200 kWh a night','from the depot model, at the 400 kW limit']:sk==='kasarani'?['1,050 of 1,200 kWh a night','since 1 Nov; full in October']:['Not available yet','needs the depot charging model per night'];
  st=[['Deliverable energy',dl[0],dl[1],sk?'':'na'],['leak',''],['Delivered',num(C.delivered_kwh)+' kWh','Measured'],['leak',''],['Required departures',num(C.departures_required),'Recorded (roster)'],['leak',`missed in October: ${num(C.departures_required-C.departures_met)}`],['Departures met',num(C.departures_met),'Recorded'],['leak',''],['Revenue','Not applicable','charging is a cost centre','na']];}
 const html=st.map(x=>x[0]==='leak'?`<li class="leak" aria-label="Leak: ${escapeHtml(x[1]||'none recorded')}"><span>${x[1]||'—'}</span></li>`:`<li class="stage ${x[3]==='na'?'na':''}"><small>${x[0]}</small><b>${x[1]}</b><span>${x[2]}</span></li>`).join('');
 return `<figure class="chainfig"><figcaption><strong>${sk?SK[sk].name:o.name} value chain, October</strong> · stages are factors; the gaps between them are leaks</figcaption><ol class="chain">${html}</ol></figure>`;}

/* ---------- Overview ---------- */
function headline(op){const o=OPS[op],T=opTotals(op),P=o.t.portfolio,res=residualOf(op);
 if(o.kind==='cost')return `October charging and depot cost, composed from the depots’ factors: ${usd(T.actual)} against a plan of ${usd(T.plan)}, ${usd(-T.variance)} over. All ${num(P.departures_met)} required departures were met, at ${usd2(P.cost_per_departure_actual)} each (plan ${usd2(r2(T.plan/P.departures_required))}).`;
 const c=P.chain;return `October contribution, composed from the sites’ factors: ${usd(T.actual)} against a plan of ${usd(T.plan)}, ${usd(-T.variance)} short. Revenue factors move it by ${usd(c.revenue_variance,true)}, cost factors by ${usd(c.cost_variance,true)}.`;}
function heroFigs(op){const o=OPS[op],T=opTotals(op),P=o.t.portfolio,A=P.allocation,res=residualOf(op),cv=P.coverage,M=o.t.portfolio_constraints,crew=M[o.crewKey],used=A.crew_visits_used??A.technician_visits_used;
 const plan=planCase(op);
 const h=(lab,val,note,cls)=>`<div class="hero"><span>${lab}</span><div class="herov">${val}</div><small>${note}</small>${cls?ec(cls):''}</div>`;
 const m12=op==='lakeside'?h('Modelled 12-month change of the plan',plan.spend===A.spend&&plan.value===A.modelled_12m_change.total?fig('port:lakeside:m12',usd(plan.value,true)):usd(plan.value,true),'Modelled, not realised: separate factors, each counted once','MODELLED')
  :op==='harvest'?h('Modelled change of the plan',`${usd(OPT['KIRI-REPAIR'].economics.net_12m,true)} · ${LS.agg?usd(OPT['MWEA-AGG'].economics.net_contract,true):'—'}`,`Kirinyaga repair over 12 months${LS.agg?'; Mwea contract over its 4 months':''}: different horizons, listed side by side, not totalled`,'MODELLED')
  :h('Modelled 12-month change of the plan',LS.tou?usd(OPT['EMB-DEADLINE'].economics.net_12m,true):'$0','Embakasi schedule, Modelled, not realised; Ruiru’s avoided $60,000 purchase is listed beside it, not added','MODELLED');
 return `<div class="heroes">${h(o.kind==='cost'?'Charging and depot cost':'Contribution',fig(`port:${op}:actual`,usd(T.actual)),`plan ${usd(T.plan)} · ${fig(`port:${op}:cov`,pct(cv.cost_recorded_share,1))} of cost on recorded facts`,'RECORDED')}
 ${h('Deviation, attributed to factors',fig(`port:${op}:variance`,usd(T.variance,true)),`${usd(res.attributed,true)} attributed to observed factors · ${usd(res.residual,true)} not explained yet (unobserved leaves)${o.kind==='cost'?'. Minus means cost above plan.':''}`,'')}
 ${h('Plan spend',fig(`port:${op}:spend`,usd(plan.spend))+` <small>of ${usd(op==='lakeside'?LS.budget:M.budget_usd_nov_dec)}</small>`,`${plan.visits} of ${crew} ${o.crewWord} in November`,'QUOTE')}
 ${m12}</div>`;}
const CARDS = {
 lakeside:()=>{const c=OPS.lakeside.t.portfolio.chain;return {
  grow:{pos:`Revenue ${usd(c.revenue)} against ${usd(c.plan_revenue)}`,f:[[`Billed kWh ${num(c.billed_kwh)} against ${num(c.plan_billed_kwh)}`,'RECORDED'],['Customer consumption: Kobo +95 kWh (+$38), Kisiwa −100 kWh (−$55), Mto −20 kWh (−$8)','RECORDED'],['New factor: Mto cooperative’s signed letter of intent, 1,650 kWh a month of daytime demand','MODELLED']]},
  optimize:{pos:`Cost to serve ${usd(c.cost_to_serve)} against ${usd(c.plan_cost_to_serve)}`,f:[['Diesel litres 3,900 against 3,300: all of the cost deviation','RECORDED'],['Kobo: 210 L a month of running after dawn that solar could carry (−$262.50)','MODELLED'],['Mto: 140 kWh metered but not billed after a meter swap (−$56)','RECORDED']]},
  protect:{pos:'1 obligation at its limit · 1 right with a deadline',f:[['Kisiwa evening supply on one generator at 95% load','RECORDED'],['Kobo battery at least 35% at 5 am: checked for every option by forward replay','MODELLED'],['Mto inverter warranty notice due 27 Nov; Kobo battery cover $64,000','EXPOSURE']]},
  assure:{pos:`${pct(OPS.lakeside.t.portfolio.coverage.cost_recorded_share,1)} of cost on recorded facts`,f:[['Kisiwa’s October maintenance-contract invoice missing: carried at plan','ESTIMATED'],['Not explained yet: Kobo 120 L above the 2% tolerance; Mto 120 kWh beyond expected losses (not priced)','DERIVED'],['Verified results: none yet; trial not started','MISSING']]}};},
 harvest:()=>{const c=OPS.harvest.t.portfolio.chain;return {
  grow:{pos:`Revenue ${usd(c.revenue)} against ${usd(c.plan_revenue)}`,f:[[`Occupied crate-days ${num(c.occupied_crate_days)} against ${num(c.plan_crate_days)}: all at Mwea (35% full against 60%)`,'RECORDED'],[`Idle capacity ${num(c.capacity_crate_days-c.occupied_crate_days)} crate-days`,'DERIVED'],['New factor: aggregator’s draft contract, 150 crates December to March','MODELLED']]},
  optimize:{pos:`Cost to serve ${usd(c.cost_to_serve)} against ${usd(c.plan_cost_to_serve)}`,f:[['Kirinyaga electricity 970 kWh (24%) above what occupancy explains (−$194)','DERIVED'],['Mwea within 0.6% of its model: high cost per crate-day is low occupancy','DERIVED'],['Electricity per crate-day: Mwea $0.1221, Kirinyaga $0.1008','DERIVED']]},
  protect:{pos:'1 batch limit breached on 6 Oct',f:[['Thika batch B-1031 above its 5 °C limit for 20–30 minutes: $2,160 at stake','EXPOSURE'],['Compensation for 6 crates downgraded: $108','RECORDED'],['Start controller replaced 8 Nov under warranty (accepted 17 Oct)','CONTRACT']]},
  assure:{pos:`${pct(OPS.harvest.t.portfolio.coverage.cost_recorded_share,1)} of cost on recorded facts`,f:[['Thika’s October service invoice missing: carried at plan','ESTIMATED'],['Every October deviation attributed to an observed factor: nothing unexplained','DERIVED'],['Verified results: none yet; witnessed start test after 8 Nov','MISSING']]}};},
 metro:()=>{const P=OPS.metro.t.portfolio;return {
  grow:{pos:'Revenue: not applicable · charging is a cost centre',f:[[`Required departures met: ${num(P.departures_met)} of ${num(P.departures_required)}`,'RECORDED'],['Ruiru can serve 6 more buses on its chargers: 2,800 of 3,200 kWh a night','MODELLED'],['Ruiru chargers in use 31% of charger-hours','MEASURED']]},
  optimize:{pos:`Cost ${usd(P.actual_cost)} against ${usd(P.plan_cost)} · ${usd2(P.cost_per_departure_actual)} a departure`,f:[['Embakasi: 55% of charging at peak price against 30% (−$2,604)','RECORDED'],['Embakasi: monthly peak 500 kW against 450 kW (−$600)','RECORDED'],['Ruiru: +$19.68 not attributed (plan is a bill total)','DERIVED']]},
  protect:{pos:'1 obligation below its limit since 1 Nov',f:[['Kasarani: 1,050 of 1,200 kWh a night since charger 2 failed; 2 departures missed ($240)','RECORDED'],['Embakasi peak at its 500 kW import limit','RECORDED'],['Ruiru peak 380 kW of 400 kW','RECORDED']]},
  assure:{pos:`${pct(P.coverage.cost_recorded_share,1)} of cost on recorded facts`,f:[['Kasarani’s October maintenance invoice missing: carried at plan','ESTIMATED'],['Embakasi’s new tariff is an assumption until the invoice confirms it','CONTRACT'],['Verified results: none yet','MISSING']]}};}};
function outcomeCards(op){const C=CARDS[op]();return `<div class="ocards">${Object.entries(LENS).map(([k,[name,ico]])=>`<article class="ocard lens-b-${k}"><div class="ocard-h">${icon(ico)}<h3>${name}</h3></div><p class="ocard-pos">${C[k].pos}</p><h4>Factors that define it</h4><ul>${C[k].f.map(([t,c])=>`<li><span>${t}</span>${ec(c)}</li>`).join('')}</ul>${link('portfolio/outcomes-by-site','Open the factor structure →')}</article>`).join('')}</div><p class="note">The four outcomes are read over one factor structure. Different evidence classes sit side by side and are never added; Protect and Assure show states, deadlines and values at stake, not money.</p>`;}
const ATTN = {
 lakeside:[['off','Off plan','kobo','Litres used 1,180 against 700 planned; 210 L a month is running after dawn that solar and the battery could carry','kobo-generator'],['at','At its limit','kisiwa','Evening supply on one generator at 95% load since generator 1 failed on 30 Oct','kisiwa-genset'],['new','New factor','mto','The cooperative’s signed letter of intent for a daytime rice huller; it lapses on 30 Nov','mto-demand'],['due','Deadline','mto','Inverter 2 failed on 28 Oct: half the daytime capacity; warranty notice due 27 Nov','mto-inverter'],['off','Off plan','mto','140 kWh metered but not billed after the 3 Oct meter swap','mto-billing'],['unobs','Not observed','kobo','120 L of fuel beyond what the generator model explains (above the 2% tolerance): investigation, no recovery claimed','kobo-generator']],
 harvest:[['off','Off plan','mwea','Occupied crate-days 4,340 against 7,440 planned (35% full against 60%)','mwea-occupancy'],['off','Off plan','kirinyaga','Electricity 24% above what its occupancy explains (tolerance 5%)','kirinyaga-energy'],['at','Limit breached','thika','A batch was above its 5 °C limit for 20–30 minutes on 6 Oct after the backup failed to start; the controller is replaced on 8 Nov','thika-backup'],['new','New factor','mwea','The aggregator’s draft contract: 150 crates, December to March','mwea-occupancy']],
 metro:[['off','Below its limit','kasarani','On plan in October. Since 1 Nov charger 2 is down: 1,050 of 1,200 kWh a night, so departures are at risk; 2 missed so far','kasarani-charger'],['off','Off plan','embakasi','55% of charging at peak price against 30% planned','embakasi-schedule'],['at','At its limit','embakasi','Monthly peak import 500 kW: at the 500 kW limit','embakasi-schedule'],['new','New factor','embakasi','From 1 Nov the tariff adds a 00:00–05:00 rate at $0.09','embakasi-schedule'],['new','New factor','ruiru','The city offers 6 more buses on a new route','ruiru-expansion'],['near','Near its limit','ruiru','Peak import 380 kW of a 400 kW limit','ruiru-expansion'],['low','Low','ruiru','Charger 7, connector 2 silent since 6 Oct; no departure depends on it','ruiru-connector']]};
function attentionList(op,sk){const rows=ATTN[op].filter(r=>!sk||r[2]===sk);if(!rows.length)return '<p class="note">No factor at this site is off plan, at a limit or newly appeared.</p>';
 return `<ul class="attn">${rows.map(([k,t,s,txt,d])=>`<li class="attn-${k}"><span class="attn-k">${t}</span><div>${sk?'':`<b>${SK[s].name}</b> · `}${txt}</div>${link(`decision/${d}`,'Decision →')}</li>`).join('')}</ul>`;}
const CONTRAST = {
 lakeside:[['Kisiwa burns the most diesel and has nothing to save.','Kisiwa used 2,400 L in October, the most in the portfolio, but every generator interval was needed: a rainy month and evening load larger than solar plus battery. Kobo used half as much, yet 210 L a month of its running after dawn is avoidable by a setting change worth a modelled $2,916 over 12 months.','kobo-generator','Kobo’s generator decision']],
 harvest:[['Mwea has the worst cost per crate-day and healthy equipment.','Mwea’s electricity per crate-day ($0.1221) is the highest, but it is within 0.6% of what its occupancy needs: it is 35% full against a 60% plan, so the lever is a customer, not a compressor. Kirinyaga looks fine ($0.1008) but uses 24% more electricity than its 80% occupancy explains: there the lever is a $350 repair.','mwea-occupancy','Mwea’s occupancy decision']],
 metro:[['An idle connector ranks below a busy depot’s fault, and the cheapest schedule is rejected.','Ruiru’s charger 7, connector 2 has been silent since 6 Oct, but no departure depends on it. Kasarani was on plan in October, yet since 1 Nov one bus is short of charge every night: that comes first. At Embakasi the cheapest bill (00:00–05:00 only, $12,975 a month) leaves 3 buses short every night, so the departure-time schedule ($13,356) wins.','kasarani-charger','Kasarani’s charger decision']]};
function contrastPanel(op){return sec('Why sites that look alike need different levers',CONTRAST[op].map(([h,p,d,l])=>`<article class="contrast"><h3>${h}</h3><p>${p}</p>${link(`decision/${d}`,`Open ${l} →`)}</article>`).join(''));}
function firstMoves(op){const P=planCase(op);return sec('First moves',`<ol class="moves">${P.rows.slice(0,3).map((r,i)=>`<li><span class="rk">${i+1}</span><div><b>${link(`decision/${decOf(r.id).id}`,optLabel(r.id))}</b><small>${SK[OPT[r.id]._site].name} · ${r.why}</small></div></li>`).join('')}</ol>${link('portfolio/act-first','Open the whole plan →')}`,'The top of the plan on Act first');}
function overviewScreen(){const op=LS.op;return `<div class="headline"><p>${headline(op)}</p></div>${heroFigs(op)}${chainStrip(op)}
 <h2 class="h2s">Outcomes and the factors that define them</h2>${outcomeCards(op)}
 <div class="grid2">${sec('Factors needing attention',attentionList(op),'Off plan, at or near an obligation limit, or newly appeared. Seen at the factor before the books show it.')}<div>${contrastPanel(op)}${firstMoves(op)}</div></div>`;}

/* ---------- Act first: the plan under budget and crews, with switches ---------- */
const WHY_FIRST = {'KIS-REPAIR':'Must do: evening supply has no backup','KOB-STOPSOC':'Largest modelled value; remote change','MTO-INV-CLAIM':'Deadline: warranty notice by 27 Nov; the huller depends on it','MTO-INV-BUYNOW':'Deadline: the huller’s letter of intent lapses 30 Nov','MTO-HULLER':'Value: new paying daytime demand','MTO-BILLING':'Value: restores billed charges; office work','MTO-METER-AUDIT':'Evidence: 120 kWh not explained yet','BAT-EVIDENCE':'Protects $64,000 of cover; nothing breaks if it waits a month',
 'THIKA-EPC-STOPGAP':'Must do: protects stock now, until 8 Nov','KIRI-REPAIR':'Largest 12-month value','MWEA-AGG':'Value: new customer, conditional on signature','KAS-OEM-STOPGAP':'Must do: departures at risk now','EMB-DEADLINE':'Largest money','RUI-ABSORB6':'Contract decision for the city'};
const VISIT = {'KIS-REPAIR':['1 crew visit','field'],'MTO-INV-CLAIM':['1 crew visit (meter check on the same visit)','field'],'MTO-INV-BUYNOW':['1 crew visit (meter check on the same visit)','field'],'BAT-EVIDENCE':['1 crew visit','field'],'KOB-STOPSOC':['Remote: vendor change + 14-day supervised trial','remote'],'MTO-HULLER':['Connection contractor (in the $1,200)','contractor'],'MTO-BILLING':['Office: billing records','remote'],'MTO-METER-AUDIT':['On the inverter visit','field'],
 'THIKA-EPC-STOPGAP':['Site staff: night rota + SMS alarm','remote'],'KIRI-REPAIR':['1 technician visit','field'],'MWEA-AGG':['1 technician visit (ethylene curtain)','field'],'KAS-OEM-STOPGAP':['Operations: one bus to Ruiru each night','remote'],'EMB-DEADLINE':['Remote: charger management schedule','remote'],'RUI-ABSORB6':['Contract: no technician work','remote']};
const PLAN_EFFECT={'MTO-INV-CLAIM':()=>[usd(-OPT['MTO-INV-CLAIM'].residual_cost),'our cost, counted in the plan’s 12-month change'],'MTO-INV-BUYNOW':()=>[usd(-OPT['MTO-INV-BUYNOW'].residual_cost),'our cost, counted in the plan’s 12-month change'],'BAT-EVIDENCE':()=>['Protects $64,000 of cover','at stake, not money; no saving claimed']};
function planCase(op){const o=OPS[op],A=o.t.portfolio.allocation,M=o.t.portfolio_constraints;
 if(op==='lakeside'){const cases=A.switches.find(x=>x.cases).cases,key=`${LS.budget}/${LS.loi?'yes':'no'}`,c=cases[key];
  let ids=[...A.recommended].map(id=>id==='MTO-INV-CLAIM'&&c.inverter==='BUYNOW'?'MTO-INV-BUYNOW':id).filter(id=>id!=='MTO-HULLER'||c.huller);
  const altBuy={id:'MTO-INV-BUYNOW',value:cases['6500/no'].value,spend:cases['6500/no'].spend,huller:true},altClaim={id:'MTO-INV-CLAIM',value:LS.loi?cases['5000/yes'].value:cases['5000/no'].value,spend:LS.loi?cases['5000/yes'].spend:cases['5000/no'].spend,huller:LS.loi};
  const win=c.inverter==='BUYNOW'?altBuy:altClaim,lose=c.inverter==='BUYNOW'?altClaim:altBuy;
  return {key,spend:c.spend,value:c.value,visits:A.crew_visits_used,ids,rows:ids.map(id=>({id,why:WHY_FIRST[id]})),win,lose,loseAffordable:lose.spend<=LS.budget,huller:c.huller};}
 if(op==='harvest'){const ids=A.recommended.filter(id=>id!=='MWEA-AGG'||LS.agg);return {spend:LS.agg?A.spend:r2(A.spend-A.spend_breakdown['MWEA-AGG']),visits:LS.agg?A.technician_visits_used:A.technician_visits_used-1,ids,rows:ids.map(id=>({id,why:WHY_FIRST[id]}))};}
 const ids=A.recommended.filter(id=>id!=='EMB-DEADLINE'||LS.tou);return {spend:LS.tou?A.spend:r2(A.spend-A.spend_breakdown['EMB-DEADLINE']),visits:A.technician_visits_used,ids,rows:ids.map(id=>({id,why:WHY_FIRST[id]}))};}
const radio = (name,val,label,on) => `<label class="sw"><input type="radio" name="${name}" value="${val}" ${on?'checked':''}> ${label}</label>`;
function switches(op){const M=OPS[op].t.portfolio_constraints;
 if(op==='lakeside')return `<fieldset class="switch"><legend>Budget for November and December</legend>${radio('sw-budget',5000,usd(5000),LS.budget===5000)}${radio('sw-budget',6500,usd(6500),LS.budget===6500)}</fieldset><fieldset class="switch"><legend>Will the cooperative extend its letter of intent past 30 Nov?</legend>${radio('sw-loi','yes','Yes',LS.loi)}${radio('sw-loi','no','No',!LS.loi)}<small>The rice huller needs inverter 2 working and 5 working days to connect.</small></fieldset>`;
 if(op==='harvest')return `<fieldset class="switch"><legend>Does the aggregator sign the off-season contract?</legend>${radio('sw-agg','yes','Yes',LS.agg)}${radio('sw-agg','no','No',!LS.agg)}<small>Budget ${usd(M.budget_usd_nov_dec)} for November and December.</small></fieldset>`;
 return `<fieldset class="switch"><legend>Does Embakasi’s time-of-use and demand-charge tariff apply? (confirm from the utility invoice)</legend>${radio('sw-tou','yes','Yes',LS.tou)}${radio('sw-tou','no','No',!LS.tou)}<small>Budget ${usd(M.budget_usd_nov_dec)} for November and December.</small></fieldset>`;}
function meter(label,used,capv,fmt){const p=Math.min(100,used/capv*100);return `<div class="meter"><div class="meterhead"><span>${label}</span><strong>${fmt(used)} of ${fmt(capv)}</strong></div><div class="metertrack" role="img" aria-label="${label}: ${fmt(used)} of ${fmt(capv)}"><span style="width:${p}%"></span></div></div>`;}
function actFirstScreen(){const op=LS.op,o=OPS[op],A=o.t.portfolio.allocation,M=o.t.portfolio_constraints,P=planCase(op),budget=op==='lakeside'?LS.budget:M.budget_usd_nov_dec,crew=M[o.crewKey];
 const rows=P.ids.map(id=>{const x=OPT[id],[cv,cn]=optCost(x),[ev,en]=PLAN_EFFECT[id]?PLAN_EFFECT[id]():optEffect(x),d=DEC_SEE_ALSO[id]||decOf(id).id;
  return [`${siteLink(x._site)}`,`<b>${optLabel(id)}</b>`,WHY_FIRST[id]||'',id==='MTO-METER-AUDIT'?'$60 <small class="cellnote">routine maintenance budget</small>':`${fig(`opt:${id}:cost`,cv)} <small class="cellnote">${whoPays(x)}</small>`,VISIT[id]?.[0]||'—',`${ev} <small class="cellnote">${en}</small>${ec(id==='MTO-BILLING'?'ECONOMIC_ACTUAL_FORWARD':id==='BAT-EVIDENCE'?'EXPOSURE':optClass(x))}`,fx(x.condition)||'—',link(`decision/${d}`,'Decision →')];});
 const say=op==='lakeside'?`Plan re-computed: spend ${usd(P.spend)}, modelled 12-month change ${usd(P.value,true)}.`:`Plan re-computed: spend ${usd(P.spend)}.`;
 let excl=[];
 if(op==='lakeside'){excl=A.excluded.filter(x=>!['MTO-INV-BUYNOW'].includes(x.id)).map(x=>[x.id,fx(x.reason)]);excl.unshift([P.lose.id,P.loseAffordable?`Under this assumption it gives ${usd(P.lose.value,true)} against ${usd(P.win.value,true)}`:`Needs ${usd(P.lose.spend)} with everything else; the budget is ${usd(budget)}`]);if(!P.huller)excl.unshift(['MTO-HULLER','The letter of intent lapses on 30 Nov; with the inverter back only on 28 Nov there is no time to connect']);}
 else if(op==='harvest'){excl=A.excluded.map(x=>[x.id,fx(OPT[x.id].reason)||fx(x.reason)]);if(!LS.agg)excl.unshift(['MWEA-AGG','The aggregator does not sign: Mwea stays at no action']);}
 else {excl=['EMB-CHEAPEST','KAS-OEM-WAIT','KAS-LOCAL','KAS-SCHEDULE','RUI-ABSORB10','RUI-4CHARGERS'].map(id=>[id,fx(OPT[id].reason)]);excl.push(['RUI-CONN-CLAIM','Deferred to the next routine visit: no departure depends on it']);if(!LS.tou)excl.unshift(['EMB-DEADLINE','Flat tariff: the schedule change saves nothing and is not recommended']);}
 const L=A.listed_not_summed;
 const listed=op==='lakeside'?[['Charges restored at Mto (12 months)',fig('stake:charges',usd(L['MTO-BILLING_charges_12m'])),'ECONOMIC_ACTUAL_FORWARD','Billed, not yet collected'],['Possible Kisiwa service credit',fig('stake:credit',usd(L['KIS-OM-SLA_potential_credit'])),'EXPOSURE','Counted only when a credit note arrives'],['Kobo battery cover',fig('stake:battery',usd(L['BAT-001_cover_exposure'])),'EXPOSURE','Protected, not gained']]
  :op==='harvest'?[['Thika batch B-1031 exposed on 6 Oct',fig('stake:batch',usd(siteM('thika').incident.batches[0].exposed_value)),'EXPOSURE','The customer’s produce; only the $108 downgrade became a liability'],['Insurance reimbursement','$0','RECORDED','Not claimed: $108 is below the $500 deductible']]
  :[['Ruiru purchase avoided by taking 6 buses',fig('opt:RUI-ABSORB6:effect',usd(OPT['RUI-ABSORB6'].avoided_capex)),'MODELLED','Avoided capital, not a saving in the books'],['Kasarani penalties so far in November',fig('stake:penalty',usd(siteM('kasarani').incident.november_to_date.penalties)),'RECORDED','Already incurred; not reversed by the plan'],['Possible Kasarani service credit if the repair is late','5% of the $400 monthly fee a business day','EXPOSURE','Counted only on a credit note']];
 const total=op==='lakeside'?`<div class="total"><span>Modelled 12-month change of this plan, not realised</span><strong>${P.key==='5000/yes'?fig('port:lakeside:m12',usd(P.value,true)):usd(P.value,true)}</strong><small>Each option changes a different factor, so each is counted once.</small></div>`
  :op==='harvest'?`<div class="total"><span>Modelled change, not realised</span><strong>${usd(OPT['KIRI-REPAIR'].economics.net_12m,true)} <small>Kirinyaga, 12 months</small>${LS.agg?` · ${usd(OPT['MWEA-AGG'].economics.net_contract,true)} <small>Mwea, 4-month contract</small>`:''}</strong><small>Different horizons: listed side by side, not totalled.</small></div>`
  :`<div class="total"><span>Modelled 12-month change, not realised</span><strong>${LS.tou?usd(OPT['EMB-DEADLINE'].economics.net_12m,true):'$0'}</strong><small>${LS.tou?'Embakasi schedule, against no action under the November tariff.':'No schedule saving on a flat tariff.'}</small></div>`;
 const paths=op==='lakeside'?sec('Two ways to restore Mto’s inverter, under this assumption',`<div class="paths">${[P.win,P.lose].map((x,i)=>`<div class="path ${i===0?'win':''}"><div class="eyebrow">${i===0?'In the plan':'Competing path'}</div><h3>${optLabel(x.id)}</h3>${kv([['Plan spend',usd(x.spend)],['Modelled 12-month change of the plan',usd(x.value,true)],['Inverter back',fdate(OPT[x.id].restore_by)],['Rice huller',x.huller?'Kept':'Lost: letter lapses 30 Nov'],['Fits the budget',x.spend<=budget?'Yes':'No']])}</div>`).join('')}</div>`,'Both paths shown side by side; the plan picks the better one that fits.'):'';
 const fieldRows=P.ids.map(id=>[VISIT[id]?.[1]==='field'?'Field work':VISIT[id]?.[1]==='contractor'?'Contractor':'Remote or office',`${SK[OPT[id]._site].name}: ${optLabel(id)}`,VISIT[id]?.[0]||'—']).sort((a,b)=>a[0].localeCompare(b[0]));
 return `<div class="grid2 controls"><div>${switches(op)}<p id="plan-live" class="vh" role="status" aria-live="polite" data-say="${escapeHtml(say)}"></p></div><div>${meter('Budget used',P.spend,budget,usd)}${meter(cap(o.crewWord)+' used',P.visits,crew,num)}${op==='harvest'&&!LS.agg?'':''}</div></div>
 ${sec('The plan: recommended set',region('Recommended set',table(['Site','What','Why first','Cost · who pays','Crew or technician','12-month result · evidence','Condition',''],rows))+total,`Must-do work first, then the set with the best modelled result that fits the budget, ${o.crewWord}, deadlines and dependencies.`)}
 ${paths}
 <div class="grid2">${sec('Field work and remote changes',region('Field work and remote changes',table(['Kind','Work','Who'],fieldRows)))}${sec('Listed beside the plan, not added',region('Listed beside the plan',table(['Item','Amount','Evidence','Why it is not added'],listed.map(([a,b,c,d])=>[a,b,ec(c),d]))))}</div>
 ${sec('Excluded or deferred, and why',region('Excluded options',table(['Option','Site','Reason'],excl.map(([id,r])=>[link(`decision/${DEC_SEE_ALSO[id]||decOf(id).id}`,optLabel(id)),SK[OPT[id]._site].name,r]))))}
 ${op==='lakeside'?sec('All four cases of the two switches',region('Four cases',table(['Budget','Letter extended','Inverter path','Rice huller','Spend','Modelled 12-month change'],Object.entries(A.switches.find(x=>x.cases).cases).map(([k,c])=>{const [b,l]=k.split('/');return [usd(+b),l==='yes'?'Yes':'No',optLabel(c.inverter==='BUYNOW'?'MTO-INV-BUYNOW':'MTO-INV-CLAIM'),c.huller?'Kept':'Lost',usd(c.spend),usd(c.value,true)];}))),'More budget never lowers the result; whether the letter is extended is what changes the path.'):''}`;}

/* ---------- Outcomes by site: each outcome's factor structure by site ---------- */
function lensGrid(op){const o=OPS[op];
 const cell=(sk,l)=>{const out=[];walk(tree(sk),n=>{if(n.lens===l&&(n.eff&&Math.abs(n.eff)>0.004||n.bound&&n.bound.state!=='ok'||n.residual))out.push(n);});
  if(l==='assure'){const est=[];walk(tree(sk),n=>{if(n.cls==='ESTIMATED'&&!n.kids)est.push(n);});
   if(!out.length&&!est.length)return '<span class="muted">All factors observed; nothing estimated</span>';
   return [...out.map(n=>`${n.label}${n.eff!=null?` (${usd(n.eff,true)})`:''}`),...est.map(n=>`${n.label}: estimated`)].join('<br>');}
  if(l==='protect'){const b=[];walk(tree(sk),n=>{if(n.bound&&n.lens==='protect')b.push(`${n.label}: ${BOUND[n.bound.state][0].toLowerCase()}`);});const ob=out.filter(n=>!n.bound).map(n=>`${n.label} (${usd(n.eff,true)})`);return [...b,...ob].join('<br>')||'<span class="muted">No limit at risk</span>';}
  const top=out.filter(n=>!n.kids||n.kids.every(k=>!(k.lens===l&&k.eff)) ).sort((a,b)=>Math.abs(b.eff||0)-Math.abs(a.eff||0)).slice(0,2);
  if(o.kind==='cost'&&l==='grow')return sk==='ruiru'?'Room for 6 more buses on existing chargers':'<span class="muted">Not applicable: cost centre</span>';
  return top.length?top.map(n=>`${n.label} (${usd(n.eff,true)})`).join('<br>'):'<span class="muted">On plan</span>';};
 return region('Site by outcome grid',`<table class="lgrid"><thead><tr><th>Site</th>${Object.values(LENS).map(([n])=>`<th>${n}</th>`).join('')}</tr></thead><tbody>${o.sites.map(sk=>`<tr><th scope="row">${siteLink(sk)}<small>${usd(siteM(sk).period.variance,true)} against plan</small></th>${Object.keys(LENS).map(l=>`<td>${cell(sk,l)}</td>`).join('')}</tr>`).join('')}</tbody></table>`);}
function waterfall(op){const o=OPS[op],T=opTotals(op),cost=o.kind==='cost';let run=T.plan;const rows=[{label:'Plan',total:true,from:0,to:run,v:run}];
 o.sites.forEach(sk=>{walk(tree(sk),n=>{const leafEff=n.eff!=null&&!n.obs&&(n.evd||n.residual)&&!(n.kids||[]).some(k=>k.evd);if(!leafEff||Math.abs(n.eff)<0.004)return;const amt=cost?-n.eff:n.eff;rows.push({site:sk,label:n.label,from:run,to:r2(run+amt),v:amt,cls:n.cls,res:n.residual,key:n.evd||`node:${sk}:${n.id}`});run=r2(run+amt);});});
 rows.push({label:'October',total:true,from:0,to:run,v:run});
 const max=Math.max(...rows.map(r=>Math.max(r.from,r.to)))*1.04,min=Math.min(0,...rows.map(r=>Math.min(r.from,r.to)));const sc=v=>(v-min)/(max-min)*100;
 const worse=v=>cost?v>0:v<0;
 return `<figure class="wf" aria-labelledby="wf-t"><figcaption id="wf-t"><strong>From plan to October ${cost?'cost':'contribution'}: the deviation attributed to factors</strong> · one view of the structure below. Solid bars are recorded, hatched are modelled splits, dashed are not explained yet.</figcaption>
 <div class="wfrows">${rows.map(r=>{const a=sc(Math.min(r.from,r.to)),w=Math.max(Math.abs(sc(r.to)-sc(r.from)),0.6);const tone=r.total?'total':worse(r.v)?'worse':'better',pat=r.res?'res':CLS[r.cls]?.[1]==='mod'?'mod':'';
  const inner=`<span class="wflabel">${r.site?`<small>${SK[r.site].name}</small>`:''}${r.label}</span><span class="wftrack" aria-hidden="true"><span class="wfbar ${tone} ${pat}" style="left:${a}%;width:${w}%"></span></span><span class="wfval">${usd(r.v,!r.total)}${r.total?'':`<small>${r.res?'not explained yet':ecw(r.cls)}</small>`}</span>`;
  return r.total?`<div class="wfrow total">${inner}</div>`:`<button class="wfrow" data-evd="${r.key}" aria-label="${escapeHtml(`${SK[r.site].name}, ${r.label}: ${usd(r.v,true)}, ${r.res?'not explained yet':ecw(r.cls)}. Show how this is worked out`)}">${inner}</button>`;}).join('')}</div>
 <details class="astable"><summary>Show as a table</summary>${region('Waterfall as a table',table(['Site','Factor','Amount','Evidence'],rows.filter(r=>!r.total).map(r=>[SK[r.site].name,r.label,usd(r.v,true),r.res?'Not explained yet':ecw(r.cls)])))}</details></figure>`;}
function outcomesBySiteScreen(){const op=LS.op,o=OPS[op],T=opTotals(op),res=residualOf(op);
 return `<p class="lede">Each site’s ${o.kind==='cost'?'cost per required departure':'contribution'} is computed from its declared factors. The plan is the same structure on planned factors, so every deviation sits at the factor where it arises; a residual appears only where a leaf factor is not observed.</p>
 ${sec(`${o.name}: ${o.kind==='cost'?'cost':'contribution'} = Σ of the three sites`,region('Portfolio composition',table(['Site',o.kind==='cost'?'Plan cost':'Plan','October','Deviation','Of which not explained yet'],[...o.sites.map(sk=>{let r=0;walk(tree(sk),n=>{if(n.residual&&n.eff!=null)r+=n.eff;});const P=siteM(sk).period;return [siteLink(sk),usd(o.kind==='cost'?P.plan.total:P.plan.contribution),fig(`node:${sk}:root`,usd(o.kind==='cost'?P.actual.total:P.actual.contribution)),usd(P.variance,true),usd(r2(r),true)];}),[`<b>Portfolio</b>`,`<b>${usd(T.plan)}</b>`,`<b>${fig(`port:${op}:actual`,usd(T.actual))}</b>`,`<b>${usd(T.variance,true)}</b>`,`<b>${usd(res.residual,true)}</b>`]])))}
 ${sec('Outcomes by site',lensGrid(op),'Each cell names the factor behind that outcome at that site. Select a site to open its structure.')}
 ${sec('Deviation attributed to factors',waterfall(op))}
 ${o.sites.map(sk=>sec(`${SK[sk].name} · ${SK[sk].type}`,factorTable(sk),`${tree(sk).label} = ${tree(sk).how}. Plan against October at every factor, with the evidence class in words.`,link(`site/${sk}`,'Open site →'),`fs-${sk}`)).join('')}`;}

/* ---------- Opportunity ---------- */
function opportunityScreen(){const op=LS.op;
 if(op==='lakeside'){const hu=OPT['MTO-HULLER'],w=OPT['MTO-WELDING'],k=siteM('kobo').daytime_headroom;
  return `${sec('Qualified demand, ranked by net contribution',region('Qualified demand',table(['Rank','Customer and site','Evidence of demand','Load','Net a month','12 months','Feasibility',''],[['1',`Mto Farmers Cooperative · ${siteLink('mto')}`,'Signed letter of intent, lapses 30 Nov',`${hu.load.kw} kW, ${hu.load.window}, ${hu.load.days_per_month} days (${num(hu.load.kwh_month)} kWh)`,fig('opt:MTO-HULLER:effect',usd(hu.economics.net_monthly,true))+ec('MODELLED'),usd(hu.economics.net_12m,true)+' after $1,200 connection','After inverter 2 is restored; 3 low-sun days a month need 225 kWh from battery or generator',link('decision/mto-demand','Decision →')]])))}
  ${sec('When the loads would run',hourStrip([[hu.load.window,'Rice huller (daytime, solar)','good'],[w.load.window,'Welding (evening, diesel)','bad']]),'Daytime load uses spare solar; evening load runs on diesel. A text list follows the chart.')}
  ${sec('Rejected demand, with break-even',region('Rejected demand',table(['Customer and site','Evidence','Net a month','Break-even','Reason'],[[`Evening welding workshop · ${siteLink('mto')}`,'Verbal enquiry, no contract',usd(w.economics.net_monthly,true)+ec('MODELLED'),`$${w.break_even_tariff_usd_per_kwh} a kWh (tariff $0.40)`,fx(w.reason)]])))}
  ${sec('Capacity without a customer',`<div class="capbox"><b>Kobo: ${k.usable_kw} kW of daytime solar, ${k.window}</b><p>Seen in the earlier five-day study (finding F-109). No customer has asked for it, so it is shown as capacity, never as an opportunity value. A signed customer would make it a demand factor and open a decision.</p>${link('opportunity-finding','Open the headroom study →')}</div>`)}`;}
 if(op==='harvest'){const ag=OPT['MWEA-AGG'],capc=OPS.harvest.t.capacity_crate_days_oct;
  return `${sec('Qualified demand, ranked by net contribution',region('Qualified demand',table(['Rank','Customer and site','Evidence of demand','Volume','Net a month','Over the contract','Feasibility',''],[['1',`Mwea Horticulture Aggregators · ${siteLink('mwea')}`,'Draft contract, not signed','150 crates, Dec–Mar, at $0.18 (4,500 crate-days a month)',fig('opt:MWEA-AGG:effect',usd(ag.economics.net_monthly,true))+ec('MODELLED'),usd(ag.economics.net_contract,true)+' after $270 set-up','Avocado with cabbage needs an ethylene curtain and a shared 5 °C setpoint',link('decision/mwea-occupancy','Decision →')]])))}
  ${sec('Rejected demand','<p class="note">No demand was rejected in this period.</p>')}
  ${sec('Capacity without a customer',region('Idle capacity',table(['Room','Capacity','Occupied','Idle crate-days','Evidence'],OPS.harvest.sites.map(sk=>{const a=siteM(sk).period.actual;return [siteLink(sk),num(capc),num(a.crate_days),num(capc-a.crate_days),ec('DERIVED')];})))+'<p class="note">Idle capacity is capacity, not value; only a customer makes it a demand factor.</p>')}`;}
 const a6=OPT['RUI-ABSORB6'],a10=OPT['RUI-ABSORB10'],ru=siteM('ruiru');const cur=ru.physical.buses*ru.physical.kwh_per_bus_night;
 return `${notice('Captive fleet: charging earns no revenue. The opportunity is more service from the same chargers.','blue')}
 ${sec('More service from the same chargers',region('Service options',table(['Option','Required a night','Deliverable a night','Capital','Result',''],[[`${optLabel('RUI-ABSORB6')} · ${siteLink('ruiru')}`,`${num(a6.required_kwh)} kWh`,`${num(a6.deliverable_kwh)} kWh`,'$0',`Feasible; avoids a ${fig('opt:RUI-ABSORB6:effect',usd(a6.avoided_capex))} purchase ${ec('MODELLED')}`,link('decision/ruiru-expansion','Decision →')]])))}
 ${sec('Ruiru: required against deliverable energy a night',capBars([['Today (14 buses)',cur],['6 more buses',a6.required_kwh],['10 more buses',a10.required_kwh]],a6.deliverable_kwh),'Today’s figure is 14 buses × 140 kWh. A text list follows the chart.')}
 ${sec('Rejected',region('Rejected service options',table(['Option','Reason'],[[optLabel('RUI-ABSORB10'),fx(a10.reason)],[optLabel('RUI-4CHARGERS'),fx(OPT['RUI-4CHARGERS'].reason)]])))}
 ${sec('Capacity without a customer',`<p class="prose">Ruiru’s chargers were in use ${pct(ru.period.actual.charger_hour_utilisation)} of charger-hours in October. That is capacity; the city’s offer is what turns part of it into service.</p>`)}`;}
function hourStrip(items){const pos=w=>{const [a,b]=w.split('-');const h=t=>{const [x,y]=t.split(':').map(Number);return x+y/60;};return [h(a)/24*100,(h(b)-h(a))/24*100];};
 return `<figure class="hours"><div class="hscale" aria-hidden="true">${[0,6,12,18,24].map(h=>`<span style="left:${h/24*100}%">${String(h).padStart(2,'0')}:00</span>`).join('')}</div>${items.map(([w,l,t])=>{const [x,wd]=pos(w);return `<div class="hrow"><span class="hlab">${l}</span><span class="htrack" aria-hidden="true"><span class="hsolar"></span><span class="hbar ${t}" style="left:${x}%;width:${wd}%"></span></span></div>`;}).join('')}<p class="note">Shaded band: daylight hours. </p><ul class="list">${items.map(([w,l])=>`<li>${l}: ${w.replace('-','–')}</li>`).join('')}</ul></figure>`;}
function capBars(items,limit){const max=Math.max(limit,...items.map(i=>i[1]))*1.08;return `<figure class="capbars">${items.map(([l,v])=>`<div class="cbrow"><span class="cblab">${l}</span><span class="cbtrack" aria-hidden="true"><span class="cbbar ${v>limit?'over':''}" style="width:${v/max*100}%"></span><span class="cblimit" style="left:${limit/max*100}%"></span></span><span class="cbval">${num(v)} kWh</span></div>`).join('')}<p class="note">Vertical line: ${num(limit)} kWh deliverable a night at the 400 kW import limit.</p><ul class="list">${items.map(([l,v])=>`<li>${l}: ${num(v)} kWh a night, ${v>limit?'above':'within'} ${num(limit)} kWh</li>`).join('')}</ul></figure>`;}

/* ---------- What changed: commitments with frozen predictions; rights tracker ---------- */
const COMMIT = {
 lakeside:[['kobo-generator','Kobo: stop the generator at 70% battery','Litres of avoidable running down by 210 L a month; battery at least 35% at 5 am every day; +$250.50 a month','Trial not started (as of 6 Nov)'],['kisiwa-genset','Kisiwa: repair generator 1','Two generators available every evening; repair at $1,800','Repair booked'],['mto-demand','Mto: connect the rice huller','1,650 kWh a month billed at $0.30; +$395 a month net','Waiting for inverter 2'],['mto-billing','Mto: fix the meter records','140 kWh a month billed ($56 a month in charges)','Records fix in progress']],
 harvest:[['kirinyaga-energy','Kirinyaga: clean the condenser and repair the leak','Electricity above the model down by 80% (range 60–90%): +$155.20 a month','Repair not done yet'],['thika-backup','Thika: start controller replaced under warranty, night cover until then','Automatic start works in a witnessed test (ACT-051); no compensation credit notes','Replacement scheduled 8 Nov'],['mwea-occupancy','Mwea: aggregator contract','4,500 crate-days a month December to March; +$485 a month net','Contract not signed']],
 metro:[['embakasi-schedule','Embakasi: charge to each bus’s departure time','Peak share near 0%; about 62,000 kWh a month at the 00:00–05:00 rate; peak at most 400 kW; every departure met; $8,082 a month below no action','Schedule not started'],['kasarani-charger','Kasarani: one bus charged at Ruiru each night until the repair','Every departure met to 9 Nov; charger 2 restored by 9 Nov','Cover from 6 Nov'],['ruiru-expansion','Ruiru: take 6 more buses','All departures met; peak import under 400 kW','Awaiting the city’s contract']]};
function whatChangedScreen(){const op=LS.op;
 const rows=COMMIT[op].map(([d,what,pred,state])=>[link(`decision/${d}`,what),pred+ec('MODELLED'),state,badge('Not yet','amber'),badge('Not yet','amber'),badge('Not yet','amber')]);
 const rt=RIGHTS_OF_OP[op].map(k=>{const r=rightsOf(k),cur=STAGE_IX[r.state];return [link(`decision/${r.dec}`,r.asset),r.type,`<span class="ministeps" aria-label="Stage ${cur+1} of 8: ${cur>=0?STAGES[cur]:'no claim stage'}">${STAGES.map((st,i)=>`<i class="${i<=cur?'on':''}" title="${st}"></i>`).join('')}</span><small class="cellnote">${cur>=0?STAGES[cur]:'No claim possible'}${r.stopped?' · '+r.stopped:''}</small>`,r.deadline?`${fdate(r.deadline)} <small class="cellnote">${daysUntil(r.deadline)} days</small>`:'—',r.cost,'None'];});
 return `${sec('Commitments: frozen prediction and three verdicts',region('Commitments',table(['Commitment','Frozen prediction','State','Operational: did the factor move, limits held?','Economic: did the money move?','Causal: how sure it was the change?'],rows))+'<p class="note">Each verdict is separate. Not proven yet is a verdict, not a pass; a prediction is never relabelled as realised.</p>')}
 ${sec('Rights tracker',region('Rights tracker',table(['Asset or contract','Type','State','Deadline','Our cost','Money recorded'],rt))+'<p class="note">Every state is set by a person from a recorded document or event. Money is recorded only when a credit note or receipt arrives.</p><p class="legal">This is not a legal decision. Coverage is decided by the supplier or insurer.</p>')}`;}

/* ---------- Scope & coverage: by site × leaf factor ---------- */
const MISSING_LEAVES = {
 lakeside:[['All sites','Usable capacity by time window','Energy management export by time window','The idle-capacity leak and any value of daytime headroom'],['Kobo','Battery cell temperature','Battery management system temperature log','A battery warranty claim'],['Kobo','Commissioning capacity test','Capacity test record (planned work PM-0447)','A battery warranty claim'],['Kisiwa','October maintenance-contract invoice','Service contractor invoice','The actual maintenance-contract line (carried at plan) and the service-credit review'],['All sites','Plan split of litres by reason','Plan at sub-factor level','Plan comparison below total litres (the split is compared with zero)']],
 harvest:[['Thika','October refrigeration service invoice','Service contractor invoice','The actual maintenance line (carried at plan)'],['All rooms','Compatibility per batch (unbilled or incompatible occupancy)','Storage ledger with commodity and segregation fields','The occupied-to-chargeable leak (assumed zero now)']],
 metro:[['Kasarani','October maintenance invoice','Service contractor invoice','The actual maintenance line (carried at plan)'],['Ruiru','Plan split by time of day','Plan at sub-factor level','Attribution of the $19.68 difference'],['Embakasi','Tariff applicability','Utility invoice with time-of-use lines','The schedule recommendation becoming unconditional'],['Embakasi, Kasarani','Deliverable energy a night (depot model)','Charger and import-limit configuration per depot','The deliverable-energy stage of the chain']]};
const PILOT_ASKS = {lakeside:['Energy management system export','Customer meter register (with effective dates)','Billing export','Mobile-money settlement statements','Fuel delivery notes and tank dips','Monthly plan or budget','One asset’s contract set (warranty, installation, service)'],
 harvest:['Storage ledger (check-in and check-out per batch)','Electricity bills','Chamber temperature log','Invoices and receipts','Quality inspection notes','Monthly plan or budget','Refrigeration service contract'],
 metro:['Charger management system session and status log','Fleet roster (departures and required charge)','Utility invoice with time-of-use and demand lines','Service tickets','Monthly plan or budget','Charger warranty and service agreement']};
function scopeScreen(){const op=LS.op,o=OPS[op],srcs=M.sources[{mini:'mini_grid',cold:'cold_chain',ev:'ev_depot'}[o.vertical]];
 const leafRows=[];o.sites.forEach(sk=>walk(tree(sk),n=>{if(!n.kids&&n.cls)leafRows.push([siteLink(sk),n.label,ec(n.cls),(SRCDEF[n.src]||SRCDEF.model)[0]]);}));
 return `${sec('Coverage by site and leaf factor',region('Coverage by site and leaf factor',table(['Site','Leaf factor','Evidence','Source record'],leafRows)),`${pct(o.t.portfolio.coverage.cost_recorded_share,1)} of October cost rests on recorded facts. Every leaf factor carries its evidence class in words.`)}
 ${sec('Not available yet, and what each missing record blocks',region('Missing records',table(['Site','Leaf factor','Record that would fill it','What it blocks'],MISSING_LEAVES[op].map(([a,b,c,d])=>[a,`${b} ${ec('MISSING')}`,c,d]))))}
 <div class="grid2">${sec('Sources connected in this demo',`<ul class="list">${[...srcs,...M.sources.all_verticals.filter(x=>!x.system.startsWith('cold:')||o.vertical==='cold')].map(x=>`<li>${plainSource(x)} <small class="cellnote">${PROV[x.provenance]}${x.cadence?' · '+x.cadence.replace(/min/g,'minute').replace(/ \(as the v7.0 probe TMP-003\)/,''):''}</small></li>`).join('')}</ul>`)}
 ${sec('Request a paid diagnostic',`<p class="prose">A bounded diagnostic on your own records, starting from exports you already have. The minimum ask for ${o.typeWord} is ${PILOT_ASKS[op].length} source categories.</p><p style="margin-top:12px">${btn('portfolio/scope/pilot','Open the pilot request',true)}</p>`)}</div>`;}
function plainSource(x){const R=[[/^cold: /,''],[/\s*\(GX-shaped[^)]*\)/,''],[/\s*\(existing operational records [^)]*\)/,''],['CPMS OCPP 1.6J log (StartTransaction, MeterValues, StatusNotification)','Charger management system session and status log'],['EMS / inverter','Energy management system or inverter export'],[', CSV export',' (CSV)'],[' + reviewed extraction rows',', with reviewed extraction'],[' + reviewed extraction',', with reviewed extraction'],['O&M/SLA','service agreement'],['EPC','installation contractor'],['ToU','time-of-use'],['QA inspection','quality inspection'],[/ \+ /g,' and '],['check-in/out','check-in and check-out']];return cap(R.reduce((a,[f,r])=>a.replace(f,r),x.system));}
function pilotScreen(){const op=LS.op,o=OPS[op];
 return `<div class="grid2 wide">${sec(`Paid diagnostic for ${o.name}`,`<p class="prose">${o.t.opening_proposition}</p><h3 class="h3s">Records we need (${PILOT_ASKS[op].length} categories, exports only)</h3><ol class="list">${PILOT_ASKS[op].map(x=>`<li>${x}</li>`).join('')}</ol>
 <h3 class="h3s">What you get</h3><ul class="list"><li>Each site’s outcomes computed from its factors, against your plan, with recorded and estimated factors marked</li><li>The deviation attributed to factors, with anything not explained shown as its own line</li><li>Factors needing attention: off plan, at a limit, or new</li><li>Decisions compared with no action and the rejected options, and the reasons</li><li>A contract-rights calendar: warranty, service and insurance positions with deadlines (not legal advice)</li><li>A verification plan with three separate verdicts for the first change</li></ul>
 <h3 class="h3s">How we check it is right</h3><ul class="list"><li>Monthly totals reconcile to your management accounts to the cent</li><li>Every figure opens its source records</li><li>One negative control: a site where the obvious saving is not real</li></ul><p class="note">Price is set in the written proposal; not shown in this mock-up. Every figure in this demo is illustrative.</p>`)}
 ${sec('Request the diagnostic','<form class="pform" onsubmit="return false"><label class="field">Your name<input name="n" autocomplete="name"></label><label class="field">Organisation<input name="o" value="'+o.name+'" autocomplete="organization"></label><label class="field">Number of sites<input name="s" inputmode="numeric" value="3"></label><label class="field">Data contact (email)<input name="e" type="email" autocomplete="email"></label><div class="form-footer"><button class="button primary" type="submit" data-pilot-submit>Request the diagnostic</button></div></form>','Example form: nothing is sent.')}</div>`;}

/* ---------- Sites directory (current operator) ---------- */
const MOVE = {kobo:'kobo-generator',kisiwa:'kisiwa-genset',mto:'mto-inverter',mwea:'mwea-occupancy',thika:'thika-backup',kirinyaga:'kirinyaga-energy',embakasi:'embakasi-schedule',kasarani:'kasarani-charger',ruiru:'ruiru-expansion'};
function sitesScreen(){const op=LS.op,o=OPS[op];
 const rows=o.sites.map(sk=>{const P=siteM(sk).period,t=tree(sk),a=ATTN[op].find(r=>r[2]===sk),d=decById(MOVE[sk]),rec=d.opts.find(id=>OPT[id].disposition==='RECOMMENDED');
  const res=o.kind==='cost'?`${usd2(t.actual)} a departure <small class="cellnote">plan ${usd2(t.plan)} · cost ${usd(P.actual.total)} against ${usd(P.plan.total)}</small>`:`${usd(P.actual.contribution)} <small class="cellnote">plan ${usd(P.plan.contribution)} · ${usd(P.variance,true)}</small>`;
  return [`${siteLink(sk)}<small class="cellnote">${SK[sk].type}</small>`,res,a?`<span class="attn-k attn-${a[0]}">${a[1]}</span> ${a[3]}`:'—',link(`decision/${d.id}`,optLabel(rec))];});
 return `${notice(`Sites of ${o.name}, the demo operator selected in the review bar.`,'blue')}${sec(`${o.name} · ${o.sites.length} sites`,region('Site directory',table(['Site',o.kind==='cost'?'Cost per required departure met':'Contribution against plan','Factor needing attention','Recommended move'],rows)),'October 2026')}`;}

/* ---------- Financials root: the operator's economic statement ---------- */
function financialsScreen(){const op=LS.op,o=OPS[op],T=opTotals(op);
 const lines=[];o.sites.forEach(sk=>walk(tree(sk),(n,d)=>{if(n.unit==='$'&&!n.obs&&d<=3&&(n.plan!=null||n.actual!=null)&&!n.evd)lines.push([sk,n,d]);}));
 const rows=lines.map(([sk,n,d])=>[d===0?siteLink(sk):'',`<span class="fac" style="--d:${d}"><b>${n.label}</b></span>`,n.plan!=null?usd(n.plan):'<span class="muted">not declared</span>',n.actual!=null?fig(`node:${sk}:${n.id}`,usd(n.actual)):'—',n.eff!=null?usd(n.eff,true):'—',ec(n.cls)]);
 const P=o.t.portfolio;let ratio;
 if(o.vertical==='mini')ratio=[['Cost to serve per billed kWh',`${usd(P.chain.cost_to_serve)} ÷ ${num(P.chain.billed_kwh)} kWh = $${(P.chain.cost_to_serve/P.chain.billed_kwh).toFixed(4)}`,`${usd(P.chain.plan_cost_to_serve)} ÷ ${num(P.chain.plan_billed_kwh)} kWh = $${(P.chain.plan_cost_to_serve/P.chain.plan_billed_kwh).toFixed(4)}`]];
 else if(o.vertical==='cold'){const e=o.sites.reduce((a,sk)=>a+siteM(sk).period.actual.energy,0),pe=o.sites.reduce((a,sk)=>a+siteM(sk).period.plan.energy,0);ratio=[['Electricity per occupied crate-day',`${usd(e)} ÷ ${num(P.chain.occupied_crate_days)} = $${(e/P.chain.occupied_crate_days).toFixed(4)}`,`${usd(pe)} ÷ ${num(P.chain.plan_crate_days)} = $${(pe/P.chain.plan_crate_days).toFixed(4)}`]];}
 else ratio=[['Cost per required departure met',`${usd(P.actual_cost)} ÷ ${num(P.departures_met)} = ${usd2(P.cost_per_departure_actual)}`,`${usd(P.plan_cost)} ÷ ${num(P.departures_required)} = ${usd2(r2(P.plan_cost/P.departures_required))}`]];
 return `${sec(`${o.name} · economic statement, October 2026`,region('Economic statement',table(['Site','Money factor','Plan','October','Effect','Evidence'],[...rows,['<b>Portfolio</b>',`<b>${o.kind==='cost'?'Charging and depot cost':'Contribution'}</b>`,`<b>${usd(T.plan)}</b>`,`<b>${fig(`port:${op}:actual`,usd(T.actual))}</b>`,`<b>${usd(T.variance,true)}</b>`,ec('RECORDED')]])),`Every site’s money factors against plan, with the evidence class in words. ${pct(P.coverage.cost_recorded_share,1)} of cost on recorded facts.`)}
 ${sec('Portfolio ratios, composed as Σ ÷ Σ',region('Portfolio ratios',table(['Ratio','October','Plan'],ratio))+'<p class="note">Portfolio ratios are the sum of numerators over the sum of denominators of comparable sites, never an average of site percentages. A site without the record is excluded and named, never counted as zero.</p>')}
 ${sec('Site economics',`<ul class="list">${o.sites.map(sk=>`<li>${link(`site/${sk}/economics`,`${SK[sk].name} economics`)}: every factor against plan, the prices and models used, and the decisions that change them</li>`).join('')}</ul>`)}`;}
